import {createExam,examMeasure,submitCase,examRecords} from './exam-model.mjs';
import {frame,tests,faults,pools} from './model.mjs';
import {comparisonValues,advancePair} from './comparison.mjs';
import {mountBench} from './bench.mjs';
import {progressKey,cleanRecords,upsert} from './guided-progress.mjs';
const $=s=>document.querySelector(s),add=(tag,text,host)=>{const el=document.createElement(tag);el.textContent=text;host.append(el);return el;};
let exam=null,actual=null,normal=null,a=null,b=null,playing=false,u=.375,v=.375,last=0,cut=true,reviewIndex=0;
function draw(){if(!a||!actual)return;a.draw(frame(normal),u);b.draw(frame(actual),v);}
function setCase(s){actual=structuredClone(s);normal={...structuredClone(s),fault:null};u=v=.375;playing=false;$('#examPlay').textContent='Reproducir a cámara lenta';draw();}
function tick(t){const dt=Math.min(.05,(t-last)/1000);last=t;if(playing&&!document.hidden){const pair=advancePair({reference:u,actual:v},frame(actual),frame(normal),dt*.25);u=pair.reference;v=pair.actual;draw();}requestAnimationFrame(tick);}
function render(){const c=exam.cases[exam.index];$('#examTitle').textContent=exam.done?'Revisión del examen':'Caso '+(exam.index+1)+' de 3';$('#examStatus').textContent=frame(c.s).status;$('#examQuestions').hidden=exam.done;$('#examResults').hidden=!exam.done;if(exam.done)return;
 $('#examTests').replaceChildren();for(const [id,label]of Object.entries(tests)){const btn=add('button',label,$('#examTests'));btn.dataset.examTest=id;btn.disabled=c.log.some(e=>e.choice===id);btn.onclick=()=>{examMeasure(exam,id);render();};}$('#examReadings').replaceChildren();for(const e of c.log)add('li',tests[e.choice]+': '+e.result,$('#examReadings'));$('#submitCase').disabled=!$('#examAnswer').value;}
function review(i){reviewIndex=i;const c=exam.cases[i];setCase(c.s);$('#examStatus').textContent=frame(c.s).status;$('#reviewTitle').textContent='Caso '+(i+1)+' · '+c.score+'/100';$('#reviewWhy').textContent='Elegiste: '+faults[c.answer].name+'. Causa: '+faults[c.s.fault].name+'. '+(c.correct?'Causa correcta. ':'La causa propuesta no coincide. ')+(c.supported?'Reuniste la evidencia causal. ':'Faltó medir: '+faults[c.s.fault].tests.filter(t=>!c.s.measured.includes(t)).map(t=>tests[t]).join(', ')+'. ')+faults[c.s.fault].why;
 $('#reviewSteps').replaceChildren();const events=c.log.length?c.log:[{choice:faults[c.s.fault].tests[0],before:{...c.s,measured:[]},correct:false,reason:'No tomaste mediciones. Empieza por reunir evidencia causal.'}];for(const [j,e]of events.entries()){const btn=add('button','Paso '+(j+1)+' · '+tests[e.choice],$('#reviewSteps'));btn.onclick=()=>showStep(e);}
 for(const id of faults[c.s.fault].tests){const btn=add('button','Contrastar '+tests[id],$('#reviewSteps'));btn.onclick=()=>showStep({choice:id,before:{...c.s,measured:[]},correct:true,reason:'Prueba causal para este caso. '+faults[c.s.fault].why});}showStep(events[0]);}
function showStep(e){setCase(e.before);const values=comparisonValues(actual,normal,e.choice);$('#reviewReading').textContent=(e.correct?'Prueba útil. ':'Elección no prioritaria. ')+e.reason+' A sano: '+values.reference+' B averiado: '+values.actual;const part={battery:'battery',drop:'ground',command:'relay',spark:'spark',fuel:'intake',compression:'piston',charge:'alternator'}[e.choice];a.select(part);b.select(part);b.highlight([part]);draw();}
function finish(){let message='Examen guardado. Tus errores y las pruebas causales pendientes ajustan el calendario y el plan semanal.';try{let records=cleanRecords(JSON.parse(localStorage.getItem(progressKey)||'[]'));for(const r of examRecords(exam))records=upsert(records,r);localStorage.setItem(progressKey,JSON.stringify(records));localStorage.setItem('mecanica.autos.exam.latest.v1',JSON.stringify(exam));}catch{message='No se pudo guardar el resultado. Puedes revisarlo aquí, pero el plan puede no conservar los cambios.';}$('#examStorage').textContent=message;$('#examGrade').textContent='Resultado: '+Math.round(exam.cases.reduce((n,c)=>n+c.score,0)/3)+'/100';$('#examCaseReviews').replaceChildren();exam.cases.forEach((c,i)=>{const btn=add('button','Revisar caso '+(i+1),$('#examCaseReviews'));btn.onclick=()=>review(i);});render();review(0);}
$('#startExam').onclick=()=>{exam=createExam();$('#startExam').hidden=true;$('#examWork').hidden=false;if(!a){a=mountBench($('#healthy'),'engine');b=mountBench($('#faulty'),'engine');a.onView?.(x=>b.setView?.(x));b.onView?.(x=>a.setView?.(x));a.cut(true);b.cut(true);requestAnimationFrame(tick);}setCase(exam.cases[0].s);render();$('#examWork').scrollIntoView({block:'start'});};
for(const id of pools.diagnosis){const o=add('option',faults[id].name,$('#examAnswer'));o.value=id;}
$('#examAnswer').onchange=()=>render();$('#submitCase').onclick=()=>{if(!submitCase(exam,$('#examAnswer').value))return;$('#examAnswer').value='';if(exam.done)finish();else{setCase(exam.cases[exam.index].s);render();}};
$('#examPlay').onclick=()=>{playing=!playing;$('#examPlay').textContent=playing?'Pausar':'Reproducir a cámara lenta';};$('#examCut').onclick=()=>{cut=!cut;a.cut(cut);b.cut(cut);$('#examCut').textContent=cut?'Cerrar corte':'Abrir corte';};document.addEventListener('visibilitychange',()=>{if(document.hidden)playing=false;});
window.examDebug=()=>({exam,actual,normal,u,v,playing,reviewIndex,a:a?.debug?.(),b:b?.debug?.()});
